cypress_script:
describe('Alert and Confirm Dialogs Tests', () => {
  it('should display alert dialog on button click', () => {
    cy.visit('https://demoqa.com/alerts');
    cy.get('#alertButton').click();
    cy.on('window:alert', (text) => {
      expect(text).to.be.not.empty;
    });
  });

  it('should not navigate away on confirm dialog click', () => {
    cy.visit('https://demoqa.com/alerts');
    cy.get('#confirmButton').click();
    cy.url().should('eq', 'https://demoqa.com/alerts');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Alert and Confirm Dialogs Tests', () => {
  test('should display alert dialog on button click', async ({ page }) => {
    await page.goto('https://demoqa.com/alerts');
    await page.click('#alertButton');
    page.on('dialog', async dialog => {
      expect(dialog.message()).toBeTruthy();
      await dialog.dismiss();
    });
  });

  test('should not navigate away on confirm dialog click', async ({ page }) => {
    await page.goto('https://demoqa.com/alerts');
    await page.click('#confirmButton');
    await expect(page).toHaveURL('https://demoqa.com/alerts');
  });
});
